<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Daybook · Personal Expense Tracker</title>
<style>
  :root{
    color-scheme: light;
    --paper:#eff2ea;
    --card:#ffffff;
    --ink:#1c2b24;
    --ink-soft:#5b6b62;
    --ink-faint:#93a096;
    --line:#d8dfd2;
    --pine:#0e3a2b;
    --green:#177a4c;
    --green-dark:#0e5a37;
    --red:#c23b2e;
    --focus:rgba(23,122,76,.25);
    --mono:ui-monospace,"SF Mono","Cascadia Mono",Consolas,"Liberation Mono",Menlo,monospace;
    --sans:"Avenir Next","Segoe UI","Helvetica Neue",system-ui,Arial,sans-serif;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    font-family:var(--sans);
    font-size:16px;
    color:var(--ink);
    min-height:100vh;
    background:
      radial-gradient(1100px 520px at 88% -12%, rgba(23,122,76,.14), transparent 62%),
      radial-gradient(900px 520px at -12% 112%, rgba(183,121,31,.10), transparent 60%),
      repeating-linear-gradient(0deg, transparent 0 27px, rgba(28,43,36,.05) 27px 28px),
      var(--paper);
  }
  ::selection{background:#bfe6cf}
  [hidden]{display:none !important}

  .wrap{max-width:1080px;margin:0 auto;padding:0 20px}

  /* ---------- masthead ---------- */
  .masthead{
    color:#f3f6ef;
    border-bottom:3px solid var(--green);
    background:
      repeating-linear-gradient(135deg, rgba(255,255,255,.035) 0 2px, transparent 2px 7px),
      linear-gradient(120deg,#0c3123,#155136 55%,#0c3123);
    box-shadow:0 4px 18px rgba(12,40,29,.18);
  }
  .masthead-inner{
    display:flex;flex-wrap:wrap;gap:22px;
    align-items:flex-end;justify-content:space-between;
    padding-top:32px;padding-bottom:28px;
  }
  .brand{display:flex;align-items:center;gap:14px}
  .mark{
    width:48px;height:48px;flex:none;
    display:grid;place-items:center;
    border:2px solid rgba(243,246,239,.85);border-radius:9px;
    font-family:var(--mono);font-weight:700;font-size:1.35rem;
    background:rgba(255,255,255,.07);
    transform:rotate(-4deg);
    box-shadow:2px 2px 0 rgba(0,0,0,.22);
  }
  .brand h1{margin:0;font-size:1.85rem;font-weight:800;letter-spacing:.03em;line-height:1}
  .tagline{margin:5px 0 0;font-size:.72rem;letter-spacing:.22em;text-transform:uppercase;color:#a9cdb6}
  .head-total{text-align:right}
  .head-label{display:block;font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;color:#a9cdb6;margin-bottom:2px}
  .head-figure{font-family:var(--mono);font-weight:700;font-size:clamp(2rem,4.5vw,3rem);line-height:1.05}
  .head-figure .cur{color:#7fd6a4;font-size:.58em;margin-right:3px;vertical-align:.42em}
  #total{display:inline-block}
  #total.pulse{animation:bump .38s ease}
  @keyframes bump{35%{transform:scale(1.09)}}
  .head-count{display:block;margin-top:5px;font-family:var(--mono);font-size:.78rem;color:#a9cdb6}

  /* ---------- layout ---------- */
  .layout{
    display:grid;grid-template-columns:355px 1fr;gap:22px;
    align-items:start;
    padding-top:26px;padding-bottom:14px;
  }
  .panel{
    background:var(--card);
    border:1px solid var(--line);
    border-radius:10px;
    box-shadow:0 1px 2px rgba(18,40,30,.05), 0 12px 30px rgba(18,40,30,.07);
    padding:20px;
  }
  .panel-side{position:sticky;top:16px}
  .block + .block{margin-top:22px;padding-top:18px;border-top:1px dashed var(--line)}
  .block-title{
    margin:0 0 14px;font-size:.72rem;font-weight:700;
    letter-spacing:.18em;text-transform:uppercase;color:var(--ink-soft);
    display:flex;align-items:center;gap:8px;
  }
  .block-title::before{content:"";width:9px;height:9px;background:var(--green);border-radius:2px;flex:none}

  /* ---------- form ---------- */
  .field{margin-bottom:13px}
  .field-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  label{display:block;font-size:.76rem;font-weight:700;letter-spacing:.05em;color:var(--ink-soft);margin-bottom:5px}
  .opt{color:var(--ink-faint);font-weight:400;font-style:italic;letter-spacing:0}
  input,select{
    width:100%;padding:9px 10px;
    font:inherit;color:var(--ink);
    background:#fbfcf9;
    border:1.5px solid #c7d1c3;border-radius:6px;
    transition:border-color .15s, box-shadow .15s, background .15s;
  }
  input:hover,select:hover{border-color:#a9b8a5}
  input:focus,select:focus{
    outline:none;border-color:var(--green);
    box-shadow:0 0 0 3px var(--focus);background:#fff;
  }
  input.invalid{border-color:var(--red);box-shadow:0 0 0 3px rgba(194,59,46,.15)}
  .amount-wrap{position:relative}
  .amount-wrap .cur{
    position:absolute;left:11px;top:50%;transform:translateY(-50%);
    font-family:var(--mono);color:var(--ink-faint);pointer-events:none;
  }
  #amount{padding-left:27px;font-family:var(--mono);font-size:1.05rem;font-weight:600}
  #form-error{
    margin:2px 0 10px;min-height:1.25em;
    color:var(--red);font-size:.85rem;font-weight:600;
  }
  #form-error.shake{animation:shake .3s ease}
  @keyframes shake{
    20%{transform:translateX(-4px)}
    45%{transform:translateX(4px)}
    70%{transform:translateX(-3px)}
    90%{transform:translateX(2px)}
  }
  #add-expense{
    width:100%;padding:11px 14px;cursor:pointer;
    font:inherit;font-weight:700;letter-spacing:.02em;color:#fff;
    background:var(--green);border:none;border-radius:6px;
    box-shadow:0 2px 0 var(--green-dark);
    transition:transform .14s, background .14s, box-shadow .14s;
  }
  #add-expense:hover{background:var(--green-dark);transform:translateY(-1px);box-shadow:0 3px 0 #0a4227}
  #add-expense:active{transform:translateY(1px);box-shadow:0 1px 0 #0a4227}
  #form-flash{
    margin-top:9px;min-height:1.1em;
    font-size:.83rem;font-weight:600;color:var(--green);
    opacity:0;transition:opacity .35s;
  }
  #form-flash.show{opacity:1}

  /* filters */
  .hint{margin:9px 0 0;font-size:.74rem;color:var(--ink-faint);line-height:1.45}
  #filter-reset{
    margin-top:12px;padding:7px 14px;cursor:pointer;
    font:inherit;font-size:.8rem;font-weight:700;letter-spacing:.04em;
    color:var(--ink-soft);background:transparent;
    border:1.5px solid #c7d1c3;border-radius:6px;
    transition:color .15s,border-color .15s,transform .15s;
  }
  #filter-reset:hover{color:var(--red);border-color:var(--red);transform:translateY(-1px)}

  /* ---------- category summary ---------- */
  .cats{
    display:grid;grid-template-columns:repeat(auto-fit,minmax(148px,1fr));
    gap:10px;margin-bottom:18px;
  }
  .cat-total{
    background:var(--card);border:1px solid var(--line);border-radius:8px;
    padding:10px 12px 11px;
    box-shadow:0 1px 2px rgba(18,40,30,.05);
    transition:transform .18s, box-shadow .18s;
  }
  .cat-total:hover{transform:translateY(-2px);box-shadow:0 6px 14px rgba(18,40,30,.10)}
  .cat-line{display:flex;align-items:center;gap:7px}
  .dot{width:9px;height:9px;border-radius:50%;background:var(--cat);flex:none}
  .cat-name{flex:1;font-size:.78rem;font-weight:600;color:var(--ink-soft)}
  .cat-amt{font-family:var(--mono);font-weight:700;font-size:.95rem}
  .cat-total.dim .cat-amt{color:#aab6ab}
  .bar{display:block;height:4px;margin-top:9px;border-radius:2px;background:#edf0e8;overflow:hidden}
  .bar i{display:block;height:100%;width:0;background:var(--cat);border-radius:2px;
         transition:width .5s cubic-bezier(.22,1,.36,1)}

  /* ---------- ledger list ---------- */
  .list-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
  .list-hint{font-size:.72rem;color:var(--ink-faint);letter-spacing:.08em;text-transform:uppercase}
  #expense-list{list-style:none;margin:8px 0 6px;padding:0}
  .expense{
    display:grid;grid-template-columns:4px 1fr auto auto;
    gap:13px;align-items:center;
    padding:11px 4px 11px 2px;
    border-bottom:1px dashed var(--line);
    animation:rowIn .22s ease both;
    transition:background .15s;
  }
  .expense:hover{background:#f6f9f3}
  @keyframes rowIn{from{opacity:0;transform:translateY(-6px)}}
  .exp-bar{width:4px;align-self:stretch;background:var(--cat);border-radius:2px}
  .exp-top{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px}
  .exp-cat{
    font-size:.68rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;
    color:#fff;background:var(--cat);
    padding:2px 8px 3px;border-radius:4px;
  }
  .exp-note{font-size:.92rem}
  .exp-date{margin-top:3px;font-family:var(--mono);font-size:.75rem;color:var(--ink-soft)}
  .exp-amount{font-family:var(--mono);font-weight:700;font-size:1rem;white-space:nowrap}
  .exp-del{
    width:27px;height:27px;cursor:pointer;
    display:grid;place-items:center;
    font:inherit;font-size:.8rem;line-height:1;color:var(--ink-faint);
    background:transparent;border:1px solid transparent;border-radius:50%;
    transition:background .15s,color .15s,border-color .15s,transform .15s;
  }
  .exp-del:hover{
    color:var(--red);background:rgba(194,59,46,.10);border-color:rgba(194,59,46,.35);
    transform:scale(1.12);
  }
  .empty{
    margin:12px 0 14px;padding:34px 18px;text-align:center;
    border:2px dashed var(--line);border-radius:8px;
    color:var(--ink-soft);font-size:.92rem;line-height:1.5;
  }

  .foot{padding:6px 20px 36px;text-align:center;font-size:.74rem;letter-spacing:.06em;color:var(--ink-faint)}

  button:focus-visible,select:focus-visible{outline:3px solid var(--focus);outline-offset:2px}

  @media (max-width:920px){
    .layout{grid-template-columns:1fr}
    .panel-side{position:static}
    .head-total{text-align:left}
  }
  @media (max-width:430px){
    .field-row{grid-template-columns:1fr}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none !important;transition:none !important}
  }
</style>
</head>
<body>

<header class="masthead">
  <div class="wrap masthead-inner">
    <div class="brand">
      <div class="mark" aria-hidden="true">$</div>
      <div>
        <h1>Daybook</h1>
        <p class="tagline">personal expense ledger</p>
      </div>
    </div>
    <div class="head-total">
      <span class="head-label">Visible total</span>
      <div class="head-figure"><span class="cur">$</span><span id="total">0.00</span></div>
      <span id="shown-count">no entries</span>
    </div>
  </div>
</header>

<main class="wrap layout">

  <!-- ============ side: entry form + filters ============ -->
  <aside class="panel panel-side">
    <section class="block">
      <h2 class="block-title">Add an expense</h2>
      <form id="expense-form" novalidate>
        <div class="field">
          <label for="amount">Amount</label>
          <div class="amount-wrap">
            <span class="cur">$</span>
            <input id="amount" type="number" step="0.01" inputmode="decimal" placeholder="0.00" autocomplete="off">
          </div>
        </div>
        <div class="field-row">
          <div class="field">
            <label for="category">Category</label>
            <select id="category">
              <option value="groceries">groceries</option>
              <option value="transport">transport</option>
              <option value="bills">bills</option>
              <option value="fun">fun</option>
            </select>
          </div>
          <div class="field">
            <label for="date">Date</label>
            <input id="date" type="date">
          </div>
        </div>
        <div class="field">
          <label for="note">Note <span class="opt">optional</span></label>
          <input id="note" type="text" maxlength="80" placeholder="e.g. weekly shop" autocomplete="off">
        </div>
        <p id="form-error" role="alert" aria-live="polite"></p>
        <button id="add-expense" type="submit">Add expense</button>
        <p id="form-flash" aria-live="polite"></p>
      </form>
    </section>

    <section class="block">
      <h2 class="block-title">Filters</h2>
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field-row">
        <div class="field">
          <label for="filter-from">From</label>
          <input id="filter-from" type="date">
        </div>
        <div class="field">
          <label for="filter-to">To</label>
          <input id="filter-to" type="date">
        </div>
      </div>
      <button id="filter-reset" type="button">Reset filters</button>
      <p class="hint">Category and date range combine — the list, the total and the category sums always reflect what is visible.</p>
    </section>
  </aside>

  <!-- ============ main: summary + ledger ============ -->
  <section class="panel">
    <div class="cats" aria-label="Per-category totals">
      <div class="cat-total" data-cat="groceries" style="--cat:#2f8f4e">
        <span class="cat-line"><span class="dot"></span><span class="cat-name">groceries</span><span class="cat-amt">0.00</span></span>
        <span class="bar"><i></i></span>
      </div>
      <div class="cat-total" data-cat="transport" style="--cat:#2b6cb0">
        <span class="cat-line"><span class="dot"></span><span class="cat-name">transport</span><span class="cat-amt">0.00</span></span>
        <span class="bar"><i></i></span>
      </div>
      <div class="cat-total" data-cat="bills" style="--cat:#b7791f">
        <span class="cat-line"><span class="dot"></span><span class="cat-name">bills</span><span class="cat-amt">0.00</span></span>
        <span class="bar"><i></i></span>
      </div>
      <div class="cat-total" data-cat="fun" style="--cat:#c2417e">
        <span class="cat-line"><span class="dot"></span><span class="cat-name">fun</span><span class="cat-amt">0.00</span></span>
        <span class="bar"><i></i></span>
      </div>
    </div>

    <div class="list-head">
      <h2 class="block-title">Ledger</h2>
      <span class="list-hint">newest first</span>
    </div>
    <ul id="expense-list"></ul>
    <div id="empty-state" class="empty" hidden><span id="empty-msg"></span></div>
  </section>
</main>

<footer class="foot">Everything is stored locally in this browser (localStorage) — nothing leaves the page.</footer>

<script>
(function(){
  "use strict";

  var STORAGE_KEY = "daybook.expenses.v1";
  var CATS = ["groceries","transport","bills","fun"];
  var CAT_COLORS = {groceries:"#2f8f4e", transport:"#2b6cb0", bills:"#b7791f", fun:"#c2417e"};
  var MON = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

  function $(id){ return document.getElementById(id); }
  var form      = $("expense-form"),
      amountEl  = $("amount"),
      categoryEl= $("category"),
      dateEl    = $("date"),
      noteEl    = $("note"),
      errEl     = $("form-error"),
      flashEl   = $("form-flash"),
      listEl    = $("expense-list"),
      totalEl   = $("total"),
      countEl   = $("shown-count"),
      emptyEl   = $("empty-state"),
      emptyMsg  = $("empty-msg"),
      fCat      = $("filter-category"),
      fFrom     = $("filter-from"),
      fTo       = $("filter-to"),
      resetBtn  = $("filter-reset");

  var chipEls = {};
  CATS.forEach(function(cat){
    var el = document.querySelector('.cat-total[data-cat="' + cat + '"]');
    chipEls[cat] = { root: el, amt: el.querySelector(".cat-amt"), bar: el.querySelector(".bar i") };
  });

  var expenses = load();
  var seq = 0;

  /* ---------- helpers ---------- */
  function genId(){
    return "e" + Date.now().toString(36) + (seq++).toString(36) +
           Math.floor(Math.random()*1296).toString(36);
  }
  function load(){
    try{
      var raw = localStorage.getItem(STORAGE_KEY);
      if(!raw) return [];
      var arr = JSON.parse(raw);
      if(!Array.isArray(arr)) return [];
      return arr.filter(function(e){
        return e && typeof e === "object" &&
               isFinite(Number(e.amount)) &&
               typeof e.date === "string" &&
               CATS.indexOf(e.category) !== -1;
      }).map(function(e){
        return {
          id: (typeof e.id === "string" && e.id) ? e.id : genId(),
          amount: Math.round(Number(e.amount)*100)/100,
          category: e.category,
          date: e.date,
          note: typeof e.note === "string" ? e.note : ""
        };
      });
    }catch(_){ return []; }
  }
  function save(){
    try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses)); }catch(_){}
  }
  function todayISO(){
    var d = new Date();
    return d.getFullYear() + "-" +
           String(d.getMonth()+1).padStart(2,"0") + "-" +
           String(d.getDate()).padStart(2,"0");
  }
  function cents(n){ return Math.round(n*100); }
  function fmt(c){ return (c/100).toFixed(2); }
  function prettyDate(iso){
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
    if(!m) return iso;
    return (+m[3]) + " " + MON[+m[2]-1] + " " + m[1];
  }
  function pulse(el){
    el.classList.remove("pulse");
    void el.offsetWidth;
    el.classList.add("pulse");
  }
  function flash(msg){
    flashEl.textContent = msg;
    flashEl.classList.add("show");
    clearTimeout(flash._t);
    flash._t = setTimeout(function(){ flashEl.classList.remove("show"); }, 2600);
  }

  /* ---------- rendering ---------- */
  function buildRow(e){
    var li = document.createElement("li");
    li.className = "expense";
    li.dataset.id = e.id;
    li.dataset.cat = e.category;
    li.dataset.date = e.date;
    li.dataset.cents = String(cents(e.amount));
    li.style.setProperty("--cat", CAT_COLORS[e.category] || "#666");

    var bar = document.createElement("span");
    bar.className = "exp-bar";

    var body = document.createElement("div");
    var top = document.createElement("div");
    top.className = "exp-top";
    var cat = document.createElement("span");
    cat.className = "exp-cat";
    cat.textContent = e.category;
    top.appendChild(cat);
    if(e.note){
      var note = document.createElement("span");
      note.className = "exp-note";
      note.textContent = e.note;
      top.appendChild(note);
    }
    var dt = document.createElement("div");
    dt.className = "exp-date";
    dt.textContent = prettyDate(e.date);
    dt.title = e.date;
    body.appendChild(top);
    body.appendChild(dt);

    var amt = document.createElement("span");
    amt.className = "exp-amount";
    amt.textContent = fmt(cents(e.amount));

    var del = document.createElement("button");
    del.type = "button";
    del.className = "exp-del";
    del.setAttribute("aria-label", "Delete this expense");
    del.textContent = "\u2715";

    li.appendChild(bar);
    li.appendChild(body);
    li.appendChild(amt);
    li.appendChild(del);
    return li;
  }

  function renderList(){
    var ordered = expenses
      .map(function(e,i){ return {e:e, i:i}; })
      .sort(function(a,b){
        if(a.e.date === b.e.date) return b.i - a.i;          // same day: newest added first
        return a.e.date < b.e.date ? 1 : -1;                 // newest date first
      });
    listEl.textContent = "";
    var frag = document.createDocumentFragment();
    ordered.forEach(function(o){ frag.appendChild(buildRow(o.e)); });
    listEl.appendChild(frag);
  }

  function applyFilters(){
    var c = fCat.value, from = fFrom.value, to = fTo.value;
    var sum = 0, visibleCount = 0;
    var catSum = {};
    CATS.forEach(function(k){ catSum[k] = 0; });

    listEl.querySelectorAll(".expense").forEach(function(li){
      var d = li.dataset.date;
      var vis = (c === "all" || li.dataset.cat === c) &&
                (!from || d >= from) &&
                (!to || d <= to);
      li.hidden = !vis;
      if(vis){
        visibleCount++;
        var v = +li.dataset.cents;
        sum += v;
        catSum[li.dataset.cat] += v;
      }
    });

    var txt = fmt(sum);
    if(totalEl.textContent !== txt){
      totalEl.textContent = txt;
      pulse(totalEl);
    }

    CATS.forEach(function(cat){
      var chip = chipEls[cat];
      chip.amt.textContent = fmt(catSum[cat]);
      chip.bar.style.width = (sum > 0 ? (catSum[cat]/sum*100) : 0) + "%";
      chip.root.classList.toggle("dim", sum > 0 && catSum[cat] === 0);
    });

    countEl.textContent =
      expenses.length === 0 ? "no entries" :
      visibleCount === expenses.length ?
        visibleCount + " " + (visibleCount === 1 ? "entry" : "entries") :
        visibleCount + " of " + expenses.length + " entries";

    var empty = visibleCount === 0;
    emptyEl.hidden = !empty;
    if(empty){
      emptyMsg.textContent = expenses.length === 0
        ? "The ledger is empty. Add your first expense — it will appear here, newest first."
        : "No entries match the current filters. Loosen them, or hit Reset filters.";
    }
  }

  function refreshAll(){ renderList(); applyFilters(); }

  /* ---------- add ---------- */
  form.addEventListener("submit", function(ev){
    ev.preventDefault();

    var raw = amountEl.value.trim();
    var val = Number(raw);
    var msg = "", badAmt = false, badDate = false;

    if(raw === "" || !isFinite(val)){ msg = "Enter a numeric amount."; badAmt = true; }
    else if(val <= 0){ msg = "Amount must be greater than zero."; badAmt = true; }
    if(!dateEl.value){
      msg = msg ? msg + " Also pick a date." : "Pick a date for the expense.";
      badDate = true;
    }

    amountEl.classList.toggle("invalid", badAmt);
    dateEl.classList.toggle("invalid", badDate);

    if(msg){
      errEl.textContent = msg;
      errEl.classList.remove("shake");
      void errEl.offsetWidth;
      errEl.classList.add("shake");
      return;
    }

    var expense = {
      id: genId(),
      amount: Math.round(val*100)/100,
      category: categoryEl.value,
      date: dateEl.value,
      note: noteEl.value.trim()
    };
    expenses.push(expense);
    save();

    errEl.textContent = "";
    amountEl.value = "";
    refreshAll();

    var visibleNow =
      (fCat.value === "all" || expense.category === fCat.value) &&
      (!fFrom.value || expense.date >= fFrom.value) &&
      (!fTo.value || expense.date <= fTo.value);
    flash(visibleNow ? "Expense added." : "Expense added — currently hidden by the filters.");

    amountEl.focus();
  });

  amountEl.addEventListener("input", function(){ amountEl.classList.remove("invalid"); });
  dateEl.addEventListener("input",  function(){ dateEl.classList.remove("invalid"); });

  /* ---------- delete (immediate, no confirm) ---------- */
  listEl.addEventListener("click", function(ev){
    var btn = ev.target.closest(".exp-del");
    if(!btn) return;
    var li = btn.closest(".expense");
    if(!li) return;
    var id = li.dataset.id;
    var idx = expenses.findIndex(function(x){ return x.id === id; });
    if(idx > -1){
      expenses.splice(idx, 1);
      save();
      refreshAll();
    }
  });

  /* ---------- filters ---------- */
  [fCat, fFrom, fTo].forEach(function(el){
    el.addEventListener("change", applyFilters);
    el.addEventListener("input",  applyFilters);
  });
  resetBtn.addEventListener("click", function(){
    fCat.value = "all";
    fFrom.value = "";
    fTo.value = "";
    applyFilters();
  });

  /* ---------- init ---------- */
  if(!dateEl.value) dateEl.value = todayISO();
  refreshAll();
})();
</script>
